<?php elseif($section==='lgpd'): ?><article class="cartao"><h2>Solicitações de titulares</h2><?php if(!$privacy):?><p>Nenhuma solicitação registrada.</p><?php else:foreach($privacy as$r):?><form class="linha-registro" method="post" action="/admin/privacy/status"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><span><b><?= e($r['requester_name']) ?></b><small><?= e($r['request_type']) ?> · <?= e($r['due_at']) ?></small></span><select name="status"><?php foreach(['open','processing','completed','rejected'] as$s):?><option value="<?= $s ?>" <?= $r['status']===$s?'selected':'' ?>><?= $s ?></option><?php endforeach;?></select><button class="botao">Salvar</button></form><?php endforeach;endif;?></article>
<?php elseif(in_array($section,['qr','pwa','menu-preview','print-menu'],true)): ?><article class="cartao"><h2><?= e($labels[$section]) ?></h2><?php if($store['published_at']):?><a class="botao primario" href="/loja/<?= e($store['slug']) ?>" target="_blank">Abrir vitrine</a><p><code><?= e(env('APP_URL','http://localhost')) ?>/loja/<?= e($store['slug']) ?></code></p><?php else:?><p>Publique a loja para liberar o endereço.</p><?php endif;?></article>
<?php elseif($section==='onboarding'): $steps=[(bool)$store['description'],!empty($categories),!empty($products),!empty($zones),!empty($hours),(bool)$store['published_at']];?><article class="cartao"><h2>Primeiros passos · <?= count(array_filter($steps)) ?>/6</h2><?php foreach([['Identidade','settings'],['Categorias','categories'],['Produtos','products'],['Entregas','zones'],['Horários','settings'],['Publicação','settings']] as$i=>$s):?><p><?= $steps[$i]?'✓':'○' ?> <a href="/admin?section=<?= e($s[1]) ?>"><?= e($s[0]) ?></a></p><?php endforeach;?></article>
<?php elseif($section==='users'): ?><article class="cartao"><h2>Novo integrante</h2><form class="formulario grade-formulario" method="post" action="/admin/user/create"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><label>Nome<input name="name" maxlength="160" required></label><label>E-mail<input type="email" name="email" maxlength="190" required></label><label>Função<select name="role"><option value="manager">Gerente</option><option value="attendant">Atendente</option><option value="waiter">Garçom</option><option value="kitchen">Cozinha</option><option value="pos">PDV</option><option value="courier">Entregador</option></select></label><label>Senha provisória<input type="password" name="password" minlength="15" maxlength="128" required></label><button class="botao primario">Criar acesso</button></form></article><article class="cartao"><h2>Equipe</h2><?php foreach($users as$member):?><form class="linha-registro" method="post" action="/admin/user/status"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$member['id'] ?>"><span><b><?= e($member['name']) ?></b><small><?= e($member['email']) ?> · <?= e($member['role']) ?> · último acesso <?= e($member['last_login_at']??'nunca') ?></small></span><?php if((int)$member['id']!==(int)$user['id']&&$member['role']!=='platform_admin'):?><label><input type="checkbox" name="active" <?= $member['active']?'checked':'' ?>> Acesso ativo</label><button class="botao">Salvar</button><?php else:?><span class="etiqueta verde">Acesso atual</span><?php endif;?></form><?php endforeach;?></article>
<?php elseif($section==='settings'): $hourMap=array_column($hours,null,'weekday');?><div class="grade duas-colunas"><article class="cartao"><h2>Dados e publicação</h2><form class="formulario" method="post" action="/admin/settings/save"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><label>Nome<input name="name" value="<?= e($store['name']) ?>" required></label><label>Cidade<input name="city" value="<?= e($store['city']) ?>" required></label><label>Telefone/WhatsApp<input name="whatsapp" value="<?= e($store['whatsapp']) ?>" required></label><label>Endereço<input name="address" value="<?= e($store['address']) ?>"></label><label>Descrição<textarea name="description"><?= e($store['description']) ?></textarea></label><label><input type="checkbox" name="store_open" <?= $store['store_open']?'checked':'' ?>> Receber pedidos agora</label><label><input type="checkbox" name="published" <?= $store['published_at']?'checked':'' ?>> Publicar catálogo</label><button class="botao primario">Salvar dados</button></form></article><article class="cartao"><h2>Identidade e operação</h2><form class="formulario" method="post" action="/admin/preferences/save"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><label>Cor principal<input type="color" name="primary_color" value="<?= e($preferences['primary_color']??'#F26B21') ?>"></label><label>Cor secundária<input type="color" name="secondary_color" value="<?= e($preferences['secondary_color']??'#111111') ?>"></label><label>Alerta de estoque mínimo<input type="number" name="minimum_stock_alert" value="<?= (int)($preferences['minimum_stock_alert']??5) ?>" min="0"></label><label>Taxa de serviço (%)<input name="service_fee_percent" value="<?= e((string)($preferences['service_fee_percent']??'0')) ?>"></label><label><input type="checkbox" name="allow_scheduled_orders" <?= !empty($preferences['allow_scheduled_orders'])?'checked':'' ?>> Permitir agendamento</label><button class="botao primario">Salvar preferências</button></form></article></div><article class="cartao"><h2>Horários de funcionamento</h2><form class="formulario" method="post" action="/admin/hours/save"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><?php foreach(['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado'] as$day=>$name):$h=$hourMap[$day]??[];?><div class="linha-registro"><b><?= e($name) ?></b><label>Abre<input type="time" name="open[<?= $day ?>]" value="<?= e(isset($h['opens_at'])?substr($h['opens_at'],0,5):'09:00') ?>"></label><label>Fecha<input type="time" name="close[<?= $day ?>]" value="<?= e(isset($h['closes_at'])?substr($h['closes_at'],0,5):'18:00') ?>"></label><label><input type="checkbox" name="closed[<?= $day ?>]" <?= !empty($h['closed'])?'checked':'' ?>> Fechado</label></div><?php endforeach;?><button class="botao primario">Salvar horários</button></form></article>
<?php elseif($section==='drivers'): $couriers=array_filter($users,fn($u)=>$u['role']==='courier'&&$u['active']);?><article class="cartao"><h2>Entregadores</h2><?php if(!$couriers):?><p>Cadastre um integrante com a função Entregador.</p><?php else:foreach($couriers as$member):?><p><b><?= e($member['name']) ?></b> · <?= e($member['email']) ?></p><?php endforeach;endif;?></article><article class="cartao"><h2>Atribuir entregas</h2><?php foreach(array_filter($orders,fn($o)=>in_array($o['status'],['confirmed','preparing','ready','out_for_delivery'],true)&&$o['order_type']==='delivery') as$o):?><form class="linha-registro" method="post" action="/admin/order/assign-courier"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$o['id'] ?>"><span><b><?= e($o['public_code']) ?> · <?= e($o['customer_name']) ?></b><small><?= e($o['status']) ?> · atual: <?= e($o['courier_name']??'não atribuído') ?></small></span><select name="courier_id"><?php foreach($couriers as$member):?><option value="<?= (int)$member['id'] ?>" <?= (int)$o['assigned_courier_id']===(int)$member['id']?'selected':'' ?>><?= e($member['name']) ?></option><?php endforeach;?></select><button class="botao">Atribuir</button></form><?php endforeach;?></article><?php endif;?>
</section></main></div><script src="/assets/admin-ui.js?v=20260903-review1" defer></script></body></html>

